import java.util.*;

public class Main {
    static final String[][] EDGES = {
        {"app:1.0", "lib-b:1.0"},
        {"app:1.0", "lib-c:2.0"},
        {"lib-b:1.0", "lib-c:1.0"},
        {"lib-b:1.0", "lib-d:1.0"},
        {"lib-c:2.0", "lib-d:2.0"},
    };

    public static void main(String[] args) {
        Map<String, List<String>> g = new LinkedHashMap<>();
        Map<String, Integer> declIdx = new LinkedHashMap<>();
        int idx = 0;
        for (String[] e : EDGES) {
            g.computeIfAbsent(e[0], k -> new ArrayList<>()).add(e[1]);
            if (!declIdx.containsKey(e[1])) declIdx.put(e[1], idx++);
        }
        Map<String, Integer> depth = new LinkedHashMap<>();
        Deque<String> q = new ArrayDeque<>();
        depth.put("app:1.0", 0);
        q.add("app:1.0");
        while (!q.isEmpty()) {
            String cur = q.poll();
            for (String nxt : g.getOrDefault(cur, List.of())) {
                if (!depth.containsKey(nxt)) {
                    depth.put(nxt, depth.get(cur) + 1);
                    q.add(nxt);
                }
            }
        }

        System.out.println("=== declared edges (root = app:1.0) ===");
        for (String[] e : EDGES) System.out.println("  " + e[0] + " -> " + e[1]);

        Map<String, String> winVer = new LinkedHashMap<>();
        Map<String, int[]> winKey = new LinkedHashMap<>();
        for (String node : depth.keySet()) {
            if (node.startsWith("app:")) continue;
            String art = node.substring(0, node.indexOf(':'));
            int d = depth.get(node), di = declIdx.get(node);
            int[] cur = winKey.get(art);
            if (cur == null || d < cur[0] || (d == cur[0] && di < cur[1])) {
                winKey.put(art, new int[]{d, di});
                winVer.put(art, node.substring(node.indexOf(':') + 1));
            }
        }

        System.out.println();
        System.out.println("=== resolved classpath (nearest wins; tie -> declared first) ===");
        for (Map.Entry<String, String> e : winVer.entrySet())
            System.out.println("  " + e.getKey() + ":" + e.getValue() + "  depth=" + winKey.get(e.getKey())[0]);

        System.out.println();
        System.out.println("=== omitted from classpath ===");
        for (String node : depth.keySet()) {
            if (node.startsWith("app:")) continue;
            String art = node.substring(0, node.indexOf(':'));
            String ver = node.substring(node.indexOf(':') + 1);
            if (ver.equals(winVer.get(art))) continue;
            int d = depth.get(node), cd = winKey.get(art)[0];
            String why = d > cd ? "deeper (" + d + " > " + cd + ")"
                                : "same depth, declared later";
            System.out.println("  " + node + "  omitted for conflict with " + art + ":" + winVer.get(art) + "  [" + why + "]");
        }
    }
}
